insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('113-2301-061','113-2301',61,'single_choice','依二次大戰後之國際法原則，關於國家取得領土主權之方式，下列敘述何者錯誤？','國家得以合意交換方式取得領土主權','對於公海上因自然力形成之島嶼，國家得先占取得其領土主權','國家得藉由人工方式改造領海外之專屬經濟海域中低潮高地為島嶼，從而取得其領土主權','國家不得以合法行使武力之方式取得他國領土主權','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-2301-062','113-2301',62,'single_choice','關於海域執法，下列敘述何者錯誤？','除非條約另有約定，否則一國海巡船舶不得於公海對他國船舶之毒品運送行為進行登檢','B 國籍船舶與C 國籍船舶在A 國鄰接區內準備共同走私毒品至D 國，A 國對該二船不得行使管轄權','發動緊追之政府船舶，如不在被緊追之外國船舶目視範圍內，即不得發動緊追','用於航行之國際海峽沿海國，有權制定與執行該海峽分道航行之規則','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-2301-063','113-2301',63,'single_choice','關於國家管轄之豁免，下列敘述何者錯誤？','一國元首於他國出訪時為子女購物所生之消費糾紛，得主張豁免該國法院之管轄','一國之國營銀行就出具之信用狀於他國所生之爭執，得主張豁免該國法院之管轄','一國依科學合作條約於他國領海探勘之公務船舶所致之損害，得主張豁免該國法院之管轄','一國卸任元首對其在任期間之職務行為，得主張豁免他國法院之管轄','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-2301-064','113-2301',64,'single_choice','個人向國際人權條約監督機構提起訴訟或申訴前，應「窮盡當地救濟」。設定該尋求國際人權機構救 濟條件之理由，下列敘述何者錯誤？','尊重國際人權條約所載不干涉（預）原則條款','允許被告國有機會修正錯誤或賠償損失','內國程序訴訟效率較高且有利判決執行','推定國家法體系正常運作以尊重管轄權','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-2301-065','113-2301',65,'single_choice','依羅馬規約之規定，下列何者不屬於國際刑事法院行使管轄權之條件？','聯合國認證之人道組織向檢察官提交情勢','締約國向檢察官提交本國情勢','聯合國安全理事會依憲章第七章決議向檢察官提交情勢','國際刑事法院檢察官依職權主動發動偵查','國際公法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-2301-066','113-2301',66,'single_choice','A 國為一複數法域國家，A 國人甲與我國人乙締結貨物買賣契約，約定關於契約之爭議適用A 國之B 州法，貨物交付地點為A 國之C 州。設甲在A 國之主要營業地為C 州，對於甲、乙之契約爭議，我 國法院應如何適用法律？','適用我國法','適用B 州法','適用C 州法','我國法、B 州法、C 州法任擇其一','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-2301-067','113-2301',67,'single_choice','甲、乙二人均具有我國之國籍。甲因在美國出生，亦具有美國籍，且定居在美國。乙因其母為德國人， 雖亦具有德國籍，然自幼與父母定居在我國。甲、乙二人成年後在臺北一見鍾情，在臺北登記結婚。 下列敘述何者正確？','甲、乙均有國籍積極衝突，故應以其各自之住所地法決定其本國法','甲、乙之國籍積極衝突為內外國籍之衝突，故應以我國法為其本國法','關於結婚成立之實質要件，甲應依美國法，乙應依我國法','甲、乙婚後，關於婚姻之效力應依其共同之本國法，亦即應依我國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-2301-068','113-2301',68,'single_choice','甲為A 國人，住所設在B 國。甲死亡時，在我國遺有不動產，在B 國遺有動產。甲之繼承人就遺產 繼承涉訟於我國法院。依A 國國際私法規定，繼承依被繼承人死亡時之住所地法。依B 國國際私法 規定，動產之繼承，依被繼承人死亡時之住所地法；不動產之繼承，依不動產所在地法。我國法院應 以何國法為準據法？','全部遺產之繼承，應以A 國法為準據法','全部遺產之繼承，應以B 國法為準據法','動產之繼承應以A 國法為準據法，不動產之繼承應以我國法為準據法','動產之繼承應以B 國法為準據法，不動產之繼承應以我國法為準據法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-2301-069','113-2301',69,'single_choice','涉外民事法律適用法第20 條第3 項規定「法律行為所生之債務中有足為該法律行為之特徵者，負擔 該債務之當事人行為時之住所地法，推定為關係最切之法律。」下列何種涉外債權契約，難以用此項 規定推定關係最切之法律？','贈與契約','保證契約','承攬契約','互易契約','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-2301-070','113-2301',70,'single_choice','A 國人甲欲收養我國人乙，關於收養之成立要件問題，我國法院應如何適用法律？','選擇適用A 國法或我國法','累積適用A 國法和我國法','並行適用A 國法和我國法','適用關係最切之我國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-2301-071','113-2301',71,'single_choice','A 國人甲將美金100 萬元貸予B 國人乙，約定借貸契約之準據法為A 國法，並以住於B 國之B 國人 丙為保證人。其後甲將其對乙所有之借款債權賣給C 國人丁，約定此買賣契約之準據法為C 國法， 並為債權移轉。關於此債權讓與相關之準據法，下列敘述何者正確？','債權讓與對於債務人乙之效力，依A 國法','債權讓與對於債務人乙之效力，依B 國法','債權讓與對於保證人丙之效力，依C 國法','債權讓與對於保證人丙之效力，依關係最切國之法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-2301-072','113-2301',72,'single_choice','關於涉外物權事件之法律適用，下列敘述何者錯誤？','物之所在地如有變更，其物權之取得、喪失或變更，依其原因事實完成時物之所在地法','物權之法律行為，其方式依該行為所應適用之法律，但依行為地法所定之方式者，亦為有效','動產於託運期間，其物權之取得、設定、喪失或變更，依其目的地法','自外國輸入我國領域之動產，於輸入前依其所在地法成立之物權，其效力依我國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-2301-073','113-2301',73,'single_choice','我國女子甲到美國工作，結識日本男子乙，二人於加拿大結婚，於美國生下一子丙。關於丙之身分可 得適用之法律，不包括下列何者？','我國法','日本法','加拿大法','美國法','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-2301-074','113-2301',74,'single_choice','我國人甲男與A 國人乙女，生有一子丙。甲死亡時遺有在我國之不動產B 屋及在A 國之不動產C 屋。 關於甲之遺產繼承，下列敘述何者正確？','關於B 屋之繼承，應適用我國法；關於C 屋之繼承，應適用A 國法','關於C 屋之繼承，依A 國國際私法應適用A 國法時，我國法院應適用A 國法','乙對甲之遺產是否有繼承權，應先依我國涉外民事法律適用法判斷甲、乙婚姻是否有效','丙對甲之遺產是否有繼承權，應定性為父母與子女間之法律關係，依我國法而定','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-2301-075','113-2301',75,'single_choice','已經訴訟繫屬於外國法院之事件，若該事件之原告又於我國法院就同一事件對被告提起訴訟。下列敘 述何者正確？','法院得在外國法院判決確定前，足認該外國判決有被承認之可能，且無重大應訴不便，以裁定停止 訴訟程序','我國法院對後繫屬之訴訟無國際管轄權，應裁定駁回之','因不得重複審理，我國法院應裁定駁回於我國重複起訴之事件','此為國際訴訟競合，我國法院訴訟繫屬因外國法院判決而自動消滅','國際私法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-3301-001','113-3301',1,'single_choice','下列關於消滅時效規定之敘述，何者錯誤？','時效因請求而中斷者，於請求後六個月內不起訴，視為不中斷','夫對於妻或妻對於夫之權利，於婚姻關係消滅後一年內，其時效不完成','以不行為為目的之請求權，消滅時效自為行為時起算','請求權罹於時效，債務人仍為履行之給付者，得依不當得利請求返還','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-3301-002','113-3301',2,'single_choice','乙為甲之意定代理人，下列敘述，何者正確？','意定代理與委任不可分','乙以甲之名義與丙訂立買賣契約，使甲間接與丙發生買賣之效力','乙以自己名義為法律行為，雖未以本人甲之名義為之，但有為本人之意思，此項意思為相對人明知 或可得而知者，稱為隱名代理','乙以自己名義為法律行為，雖未以本人甲之名義為之，但有為本人之意思，此項意思為相對人明知 者，亦構成直接代理','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-3301-003','113-3301',3,'single_choice','甲受輔助宣告，未經輔助人同意，將其所有之A 屋出賣並移轉所有權登記於乙。嗣後，乙因財務困 窘，未能依約給付價金。下列敘述，何者錯誤？','買賣契約效力未定','不動產所有權移轉行為效力未定','甲依所有物返還請求權，向乙主張返還A 屋，應經輔助人同意','甲對乙提起民事訴訟，應經輔助人同意','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-3301-004','113-3301',4,'single_choice','甲將A 屋出租於乙，乙與其配偶丙及子女丁住於A 屋。下列敘述，何者錯誤？','承租人乙應以善良管理人之注意義務保管A 屋，如因承租人乙之配偶丙應負責任之事由，致A 屋 毀損時，乙應負擔損害賠償責任','因乙之輕過失導致A 屋失火而毀損時，甲得對乙主張侵害所有權之損害賠償責任','乙依約定之方法對A 屋為使用收益致有毀損，無須對甲負損害賠償責任','租賃關係存續中，租賃物如有修繕之必要，應由出租人負責者，承租人應即通知出租人','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-3301-005','113-3301',5,'single_choice','下列關於雙方或自己代理禁止之敘述，何者正確？','禁止自己代理之規定，僅適用於意定代理，不及於法定代理','甲父贈與A 地於二歲之子乙，甲父得代理其子乙與自己訂立有效之贈與契約','甲贈與秘書乙A 地一筆，乙代理甲辦理移轉A 地所有權移轉登記於自己名下，該移轉登記效力未定','甲未經出賣人乙與買受人丙之許諾，代理雙方訂立A 地買賣契約，該買賣契約無效','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-3301-006','113-3301',6,'single_choice','下列關於法人責任之敘述，何者錯誤？','法人對於其董事因執行職務所加於他人之損害，僅由法人單獨負賠償責任','董事代表法人與他人訂立之契約，由法人單獨負擔履約與債務不履行之責任','法人之受僱人因執行職務，不法侵害他人之權利者，原則上由法人與該行為人連帶負損害賠償責任','法人之代理人，關於債之履行有故意或過失時，法人應與自己之故意或過失負同一責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-3301-007','113-3301',7,'single_choice','甲畫家受監護宣告，在心智清醒時，將代理權授與乙，讓乙代理銷售甲之畫作。假設乙無過失不知甲 受監護宣告，以甲之代理人名義與丙訂立買賣契約，並以移轉所有權之意思將甲之畫作交付於善意無 過失之丙。詎料甲之監護人拒絕承認乙之代理行為，下列敘述，何者正確？','丙是善意無過失，故可以善意取得甲之畫作','甲在心智清醒時授與乙代理權，該授權有效','乙縱使無過失，仍然須對丙負損害賠償責任','乙因非故意，所以無須對丙負損害賠償責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-008','113-3301',8,'single_choice','甲為避免債權人之強制執行，遂將名下之A 地與乙通謀虛偽訂立買賣契約，並辦理所有權移轉登記 於乙名下。乙去世後，由其子丙繼承A 地，並辦理登記完畢。嗣後丙將該地出租於丁，並設定普通抵 押權於戊。丙、丁及戊皆善意不知上述通謀虛偽情事。下列何人得主張民法第759 條之1 登記公信力 之保護？','僅丁一人','僅戊一人','丁及戊','丙、丁及戊','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-009','113-3301',9,'single_choice','乙自稱其為甲之代理人，將甲之高級音響出售於丙，於收受約定價金後，交付該音響。下列敘述，何 者錯誤？','乙為無權代理，其以甲之名義所為之法律行為效力未定','丙得定相當期限，催告甲確答是否承認','丙得善意取得該音響之所有權','僅於丙不知乙無代理權時，丙得於甲承認前撤回其法律行為','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-010','113-3301',10,'single_choice','50 歲之某甲於民國（下同）99 年12 月1 日出國自助旅行，未如期返家，其配偶乙到處打聽遍尋不 著，至100 年1 月7 日仍音訊全無，乙於107 年6 月1 日向法院聲請對甲為死亡宣告，法院於107 年 12 月1 日對甲為死亡宣告，該裁定於107 年12 月21 日確定，甲被推定死亡之時間為何？','107 年1 月1 日','107 年1 月7 日','107 年12 月1 日','107 年12 月21 日','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-011','113-3301',11,'single_choice','下列何種契約，其標的雖陷於自始客觀不能，仍為有效？','特定物之買賣契約','債權買賣契約','不動產租賃契約','動產贈與契約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-012','113-3301',12,'single_choice','甫上高中16 歲之甲，為上學之便，逕以父母給予之壓歲錢向自行車行老闆乙購買新臺幣8,000 元之 自行車一台。雙方達成合意後，乙為製作售後服務卡，並登錄消費者資料時，始發現甲原來尚未成年。 下列敘述，何者正確？','甲未得法定代理人同意，故甲、乙間之買賣契約無效','甲係以允許處分之財產購買自行車，故甲、乙間之買賣契約有效','甲購買自行車上學，非屬依其年齡及身分之日常生活所必需，故甲、乙間之買賣契約無效','若甲之法定代理人知悉後，認以自行車上學過於危險，為保護未成年人之利益，得撤銷甲、乙間之 買賣契約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-013','113-3301',13,'single_choice','甲向乙表示願以新臺幣（下同）50 萬元購買其所有之A 車，並支付乙10 萬元定金，但乙隔日卻後悔 不賣了。依民法規定，下列敘述，何者正確？','因乙已收受定金，視為雙方買賣契約成立','定金為不要物之從契約，雙方約定即可成立','因乙之反悔不賣，甲得請求乙給付20 萬元','乙僅須返還甲10 萬元，即可後悔不賣','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-014','113-3301',14,'single_choice','下列關於民法第425 條之1 租賃關係推定之敘述，何者錯誤？','土地及其土地上之房屋不同屬於一人所有，而將土地所有權讓與他人時，推定在土地受讓人與房屋 所有權人間，有租賃關係存在','該條規定於移轉之房屋為「未辦保存登記之違章建築」，亦有其適用','該條規定之土地上之房屋，須有相當之價值','該條規定，適用於其增訂前發生之事實','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-015','113-3301',15,'single_choice','甲居住於臺南市，向高雄市之乙購買乙所有之A 車，約定於5 月5 日交付，但乙因事未於當日依約 交付。嗣後發現A 車於5 月6 日毀於高雄市發生之火災。下列敘述，何者正確？','火災為通常事變，甲不得請求損害賠償','不可歸責於乙，乙依民法第225 條規定免除責任','甲得依民法第226 條有關給付不能規定，請求損害賠償','乙不負遲延給付之損害賠償責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-3301-016','113-3301',16,'single_choice','下列關於要約與要約引誘之敘述，何者錯誤？','要約僅得向特定人為之，要約引誘，則得對不特定人為之','甲建商在報上刊登廣告宣傳將在臺北車站附近推出新建案，此則廣告屬要約引誘','設置自動販賣機陳列商品標價販售，係為要約','要約引誘是一種意思通知','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-017','113-3301',17,'single_choice','甲委託乙依其身高及需求，設計製作一套工作桌椅。甲乙之契約屬於下列何種類型？','委任契約','買賣契約','僱傭契約','承攬契約','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-018','113-3301',18,'single_choice','甲將自己所有之A 牌機車贈與乙，乙表示同意。下列敘述，何者正確？','贈與為單獨行為','甲於贈與成立後，若事後反悔，在贈與物之權利未移轉前，原則上得撤銷甲與乙間之贈與','甲與乙之贈與經公證後，在贈與物之權利未移轉前，甲得撤銷贈與','贈與之物如有瑕疵，贈與人原則上應負擔瑕疵擔保責任','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-019','113-3301',19,'single_choice','甲為古畫修復師，承接乙博物館古畫修復工程。由於古畫修復需要特殊材料，因此，雙方約定，由甲 提供材料協助古畫修復，並於工作完成時給付報酬。下列敘述，何者錯誤？','古畫修復師承接古畫修復工程，屬承攬契約','甲縱使提供材料致古畫價值提升，依約乙仍保有其所有權','由於甲以自己材料修復古畫，該材料已與古畫附合，且經甲之加工，致古畫價值倍增，則甲取得古 畫之所有權','如甲乙間之修復契約不成立時，因甲提供材料修復古畫，該材料與古畫附合，故古畫可視為主物， 古畫所有權屬於乙','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-020','113-3301',20,'single_choice','甲男與乙女結婚，育有二子丙、丁，皆未成年。甲因車禍死亡，甲生前是家中唯一經濟來源，甲之父 母戊、己同住。甲還有從小感情就很好未婚同住但已有固定工作之妹妹庚。下列關於肇事者侵權責任 之敘述，何者錯誤？','乙女對肇事者得請求精神慰撫金','丙與丁得對肇事者請求扶養費用之賠償','庚因甲之過世對肇事者請求精神慰撫金損害賠償','戊、己得向肇事者請求餘命期間之扶養費損害賠償','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-021','113-3301',21,'single_choice','甲乙丙丁四人與A 約定負連帶責任，向A 借用新臺幣（下同）500 萬元，其內部分擔比例為 2：2：5：1。嗣後，A 免除甲分擔部分之債務後，對乙之財產聲請強制執行並全部獲償。乙向其他連 帶債務人求償時，因丙破產毫無財產可為清償時，乙得向何人分別求償多少金額？','對甲求償160 萬元、對丁求償80 萬元','對甲求償100 萬元、對丁求償100 萬元','對丁求償133 萬元（四捨五入）','對丁求償50 萬元','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-022','113-3301',22,'single_choice','2024 年3 月1 日，甲於報紙上刊登一則廣告，表示在同年3 月10 日前能答出其所出之數學難題，將 給付新臺幣（下同）2 萬元報酬作為獎勵。乙、丙、丁先後在不同地方解出正確答案。乙最先完成解 答，但丙最先通知甲完成解答，甲檢視答案為正確後，立即匯出報酬於丙。下列敘述，何者正確？','若甲於刊登廣告之翌日，未有人提出解答前，得無條件撤回廣告','乙有報酬請求權，得向丙主張不當得利，請求交付所受領之2 萬元報酬','乙、丙、丁得向甲請求平分報酬','甲必須再對乙支付報酬，不得拒絕。惟甲得事後對丙主張不當得利，請求返還報酬','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-023','113-3301',23,'single_choice','甲向乙借款新臺幣10 萬元，丙與乙訂立保證契約，擔保該借款債務之履行。下列關於保證契約之敘 述，何者正確？','甲對乙因借款契約所生之抗辯，丙不得主張之','丙不得以甲對乙之債權主張抵銷','若乙對甲起訴請求返還借款，其對丙基於保證契約所生之債權，發生中斷時效之效力','縱丙拋棄先訴抗辯權，仍得於乙就甲之財產強制執行而無效果前，對於乙拒絕清償','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-3301-024','113-3301',24,'single_choice','甲向乙購買乙使用2 年之A 手錶，該錶之表面有輕微刮傷，惟乙於締約時故意不告知甲，雖甲於締約 時已檢查看過，但於交付後始發現該瑕疵。下列敘述，何者正確？','甲得對乙主張權利瑕疵擔保責任','甲得請求乙另行交付無瑕疵之手錶','如甲因重大過失未發現手錶瑕疵，甲僅得對乙行使契約解除權','如甲因重大過失未發現手錶瑕疵，甲仍得對乙請求減少價金','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-3301-025','113-3301',25,'single_choice','甲向乙購買一批貨物，該貨物之貨款為新臺幣（下同）1 萬元，於清償期屆至後1 年，甲仍未清償。 下列敘述，何者錯誤？','乙得請求依法定利率計算該貨款1 萬元之遲延利息。但約定利率較高者，仍從其約定利率','若甲乙間無債權不得讓與之特約時，乙得將該1 萬元買賣價金請求權讓與於第三人丙。但非經乙或 丙通知甲，對於甲不生效力','若甲乙間無債權不得讓與之特約，乙將該1 萬元買賣價金請求權讓與於第三人丙時，丙將乙所立之 讓與字據提示於甲者，對於甲即生效力','若第三人丁與甲訂立契約承擔該1 萬元買賣價金債務，於契約成立時，該債務即由丁承擔','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-3301-026','113-3301',26,'single_choice','甲向乙無息借款新臺幣（下同）500 萬元，並將其名下市值700 萬元之A 地，設定第一順位普通抵押 權於乙。嗣後，甲向丙無息借款600 萬元，遂就A 地設定第二順位普通抵押權於丙。乙死亡時，甲為 乙之唯一繼承人。下列敘述，何者正確？','第一順位抵押權為甲之利益，仍為存續','A 地之所有權與第一順位抵押權均歸屬於甲，甲之A 地所有權因混同而消滅','丙得受完全之清償','丙從第二順位抵押權人，升進為第一順位抵押權人','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-3301-027','113-3301',27,'single_choice','甲乃A 地所有人與A 地上之B 屋所有人，並登記為A 地所有人與B 屋所有人。B 屋左側有車庫。該 車庫獨立於B 屋，但可由B 屋直通車庫。甲於民國113 年間，僅以B 屋設定普通抵押權於乙，用以 擔保其對乙所負新臺幣（下同）5,000 萬元借款債務與因該筆借款所生之100 萬元利息債務。甲屆期 遲未清償5,000 萬元借款及100 萬元利息。下列何者不為乙之B 屋抵押權之效力所及？','A 地','B 屋之車庫','100 萬元利息債務','甲對乙所負之遲延利息債務','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-3301-028','113-3301',28,'single_choice','甲名下有一間公寓，該公寓之專有部分包括A 騎樓。詎該公寓所屬管理委員會乙未經甲之同意，擅自 將A 騎樓出租並交付於善意之丙，丙搭建衣物網架，供夜市擺攤使用。下列敘述，何者錯誤？','甲得依所有權妨害除去與所有物返還請求權，訴請丙拆除衣物網架並交還A 騎樓','雖乙、丙間之租約有效，但甲得向丙請求返還相當於租金之不當得利','對甲而言，丙占用A 騎樓乃善意之無權占有人','甲得向乙請求返還其出租A 騎樓所收取租金之不當得利','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-3301-029','113-3301',29,'single_choice','甲、乙、丙、丁共有市價新臺幣（下同）300 萬元之A 地，應有部分均等，約定A 地由丙管理。嗣 後，丙對甲、乙、丁表示變為以行使地上權之意思而占有，復和平、公然、繼續占有A 地達20 年。 之後，甲因需錢孔急，各向乙、丁借款50 萬元，甲並就其應有部分設定同額之第一次序普通抵押權 （下同）於乙、第二次序抵押權於丁。乙死亡時，甲為乙之唯一繼承人。下列敘述，何者正確？','乙之抵押權因混同而消滅，丁則遞升為第一次序抵押權人','丙得請求登記為A 地之地上權人','甲得僅以其應有部分已達半數為由，主張A 地由其管理','甲應按其對於乙所負債務數額，由甲之應繼分內扣還','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-3301-030','113-3301',30,'single_choice','甲好意順道駕車載送其同事乙返家，途中不慎與對向由丙駕駛之車輛互撞。經鑑定結果，就此交通事 故之發生，甲之過失比例為30%、丙之過失比例為70%。因該事故而受傷住院治療月餘之乙，於請求 甲、丙賠償其因此所受損害時，下列敘述，何者錯誤？','乙得對丙請求賠償全部損害','乙得對甲請求賠償全部損害','乙僅得對甲、丙分別請求賠償按其過失比例之損害','乙請求丙賠償全部損害時，丙得主張乙應承擔甲之過失，故僅賠償乙所受損害之70%','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-3301-031','113-3301',31,'single_choice','甲、乙、丙、丁、戊公同共有A 車，並分別共有B 地與未辦保存登記之C 屋，應有部分均等。除契 約另有約定者外，下列敘述，何者錯誤？','處分A 車共有物，得經甲、乙、丙三人同意行之','B 地設定農育權，得經甲、丙、丁三人同意行之','改良B 地，得經丙、丁、戊三人同意行之','簡易修繕C 屋，得由乙單獨為之','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-3301-032','113-3301',32,'single_choice','甲為A 地所有人，乙為B 地所有人，並登記於土地登記簿，A 地與B 地相鄰。甲於A 地上建築C 屋， 因測量有誤，致C 屋有部分位於B 地之上。下列敘述，何者正確？','若乙於C 屋建築時明知該屋越界，則乙於C 屋建成1 年後，請求甲拆除C 屋越界建築之部分，有 理由','若乙知甲越界建築時即向甲提出異議，則法院不得斟酌公共利益與當事人利益，命甲免為全部或一 部之移除','若乙於C 屋建成之時，方知甲越界建築且即時提出異議，則乙得請求甲拆除越界建築','若甲故意越界建築，乙於C 屋建築時明知此事，但並未即向甲提出異議，則乙請求甲拆除C 屋越 界建築之部分，無理由','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-3301-033','113-3301',33,'single_choice','甲名下有A 地及A 地上之B 屋，甲於民國113 年2 月僅以A 地設定典權於乙，詎B 屋於同年7 月因 豪雨土石流致全部滅失。下列敘述，何者正確？','甲乙間原本推定之租賃關係，於B 屋滅失後歸於消滅','甲乙間原本視為已有地上權之設定，於B 屋滅失後歸於消滅','B 屋因土石流而滅失後，乙之典權即歸於消滅','甲乙間原本視為已有地上權之設定，於B 屋滅失後並未消滅','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-3301-034','113-3301',34,'single_choice','甲將其名下之A 地，設定普通地上權於乙建築房屋，約定每年地租新臺幣（下同）30 萬元，存續期 間20 年。乙於A 地上建築B 屋後，為週轉資金，將該地上權與B 屋同時設定普通抵押權於丙，均已 辦畢登記。丁擅自占用A 地與B 屋放置廢棄物，致抵押標的價值減少，乙屢次勸阻無效，擬請求排 除侵害，或拋棄其地上權。下列敘述，何者錯誤？','丙得請求乙於所受利益之限度內，提出與減少價值相當之擔保','乙拋棄其地上權，非經丙之同意，不得為之','乙得向甲支付未到期之地租30 萬元後，拋棄其地上權','乙得訴請丁清空廢棄物、遷出B 屋並交還A 地','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-3301-035','113-3301',35,'single_choice','甲乃A 汽車所有人，乙經營貨運行。甲請求乙答應出借新臺幣（下同）10 萬元於自己。乙告知：甲 應以A 車，作為該筆10 萬元借款債務之擔保，乙始可能出借10 萬元於甲。下列關於A 汽車之可能 擔保型態，何者錯誤？','甲將A 汽車所有權讓與擔保於乙','甲得以A 汽車設定抵押權於乙','甲得以A 汽車設定留置權於乙','甲得以A 汽車設定質權於乙','民法','財產法','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-3301-036','113-3301',36,'single_choice','甲男與乙女結婚後，生子丙。丁男與戊女結婚後，生女庚。於甲過世，且丁、戊離婚之後，乙與丁再 婚。丙與庚成年後，他們是否可以結婚？','不可以，因為丙與庚為旁系血親二親等之親屬','不可以，因為丙與庚為旁系姻親二親等之親屬','可以，因為丙與庚為旁系姻親二親等之親屬','可以，因為丙與庚既不是血親也不是姻親','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-037','113-3301',37,'single_choice','甲男與乙女為夫妻，甲婚後與乙之姪女丙發生外遇，乙忿而與甲離婚，甲於離婚後與丙結婚，甲丙婚 姻效力為何？','有效','無效','得撤銷','效力未定','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-038','113-3301',38,'single_choice','甲男、乙女婚後生下丙男、丁男。丙男成年後與戊女結婚，生下己男。在己八歲時，某日，丙男不幸 死亡，留下戊、己孤兒寡母，生活艱難。丁男經常予以關懷，遂與戊女日久生情，也與己男有良好互 動。丁男得否與戊女結婚？若戊同意，丁得否收養己？','丁不得與戊結婚，亦不得收養己','丁不得與戊結婚，但得收養己','丁得與戊結婚，亦得收養己','丁得與戊結婚，但不得收養己','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-039','113-3301',39,'single_choice','甲男乙女結婚後，未約定夫妻財產制。甲婚前有X 屋一棟，價值新臺幣（下同）1,500 萬元，但貸款 300 萬元。婚後，甲將該房屋出租，每月租金5 萬元，並以之償還貸款，五年後清償完畢。婚後甲又 以其營業所得1,000 萬元購買價值2,500 萬元之Y 屋，先向銀行貸款1,500 萬元。嗣後，甲將X 屋出 賣，得款1,500 萬元，並償還銀行貸款。甲乙離婚時，乙無任何財產。乙得向甲請求多少金額剩餘財 產分配？','550 萬元','600 萬元','650 萬元','700 萬元','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-040','113-3301',40,'single_choice','夫妻離婚時，關於擔任未成年子女親權人之規定，下列敘述，何者錯誤？','夫妻為兩願離婚時，得協議何者擔任親權人，一方或雙方共同擔任均可','夫妻於判決離婚時，不得協議何者擔任親權人，應由法院依子女最佳利益酌定之','關於親權人之協議不利於子女時，法院得依職權為子女之利益改定之','法院得依職權，為未擔任親權人之一方酌定其與未成年子女會面交往之方式及期間','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-041','113-3301',41,'single_choice','甲男與乙女結婚後，與甲之寡母同住並生有二女。乙自懷孕生子後即辭職在家照顧女兒，操持家務， 孝敬婆婆。婚後十年，甲有外遇，與丙女同居長達五年而不返家，丙為甲生下一子。下列敘述，何者 錯誤？','乙得向甲請求分居五年期間之家庭生活費用','甲為唯一有責者，但依其情形，仍有可能得向乙女提起裁判離婚之訴訟','乙女得依民法第1052 條第1 項規定，以絕對裁判離婚事由向法院請求離婚','甲乙依法為兩願離婚登記後，乙因無過失尚得向甲請求給付贍養費','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-042','113-3301',42,'single_choice','甲男與乙女結婚後，甲罹患重大不治之精神疾病。乙訴請法院裁判離婚獲准。嗣後，甲欲主張裁判離 婚後陷於生活困難，請求乙給付贍養費，是否有理由？','甲罹患精神疾病，係因己方之事由導致裁判離婚，屬於有過失之一方，故甲請求乙給付贍養費無理由','甲罹患精神疾病，並無過失，故甲請求乙給付贍養費有理由','乙對於離婚事由並無可歸責之處，屬於無過失之一方，故甲請求乙給付贍養費無理由','甲罹患精神病之過失，較諸乙主動請求離婚之過失為輕，故甲請求乙給付贍養費有理由','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-043','113-3301',43,'single_choice','甲男與乙女為夫妻，育有5 歲之子丙。嗣後，甲乙離婚，約定由乙獨立擔任丙之親權人。下列敘述， 何者正確？','甲對丙之親權未停止','甲因未擔任丙之親權人，故得停止支付對丙之扶養費','經甲同意時，乙得代理丙將丙出養於丁','若甲反對，乙不得代理丙出賣丙之A 屋','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-3301-044','113-3301',44,'single_choice','60 歲之甲受輔助宣告，甲有配偶乙、子女丙。下列何種情形符合民法之規定？','以遺囑指定乙之應繼分為三分之二，丙之應繼分為三分之一','乙受監護宣告，甲擔任乙之監護人','朋友丁作成代筆遺囑時，甲擔任遺囑見證人','乙留有遺囑後死亡，甲擔任乙之遺囑執行人','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-045','113-3301',45,'single_choice','甲中年喪妻，有乙丙丁三子。某日，甲無權代理乙，將乙之A 車出賣於善意之戊。隔日，甲因故死 亡。下列敘述，何者錯誤？','甲之無權代理行為，因乙之繼承甲而有效','乙得拒絕承認甲之無權代理行為','戊在乙未承認或拒絕甲之無權代理行為前，得撤回之','若甲之無權代理行為不生效力，乙丙丁因繼承甲而對戊，負損害賠償責任','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-046','113-3301',46,'single_choice','有關民法第1149 條規定之遺產酌給請求權，下列敘述，何者正確？','遺產酌給權人之子女得因酌給權人之死亡，而繼承請求酌給權利','受酌給人原則上應為不能維持生活而無謀生能力之人','就遺產酌給之數額，僅得由法院酌給於權利人','民法明定酌給之數額，不得侵害特留分','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-047','113-3301',47,'single_choice','甲有乙丙丁戊四子，民國111 年1 月1 日甲死亡後，乙隱匿甲遺產中之一幅名畫，且丙詐害債權人己 之權利而將甲之遺產毀損。假設甲之遺產不足清償己之全部債務，依民法規定，己就不足清償之部分， 不得從下列繼承人之固有財產中清償？','丙與戊','丁與戊','乙與丁','丙與丁','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-048','113-3301',48,'single_choice','甲得知妻乙懷孕，喜出望外，卻不幸執勤時因公殉職。甲之父丙因悲哀過度亦隨即病歿。丙遺有房屋 一棟，其配偶已死亡，其子女除甲外，尚有甲之姐丁。丁主張應由其單獨繼承丙之房屋，有無理由？','有理由。因甲已死亡，應由丁繼承','無理由。因胎兒有代位繼承權','有理由。因丙死亡時，胎兒仍未出生','無理由。因胎兒未出生前，應由乙繼承','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-049','113-3301',49,'single_choice','甲父母雙亡，有一子丙已成年。乙有一子丁，丁有一子戊已成年，長年住在國外。其後，甲與乙結婚， 並收養丁為養子，但戊並不知情。乙與丙感情不睦，某日二人激烈衝突，丙竟持刀殺乙既遂，而受刑 之宣告。丙服刑期間，甲丁因事故同時死亡。甲之遺產應由何人繼承？','丙單獨繼承','丁單獨繼承','戊單獨繼承','無人可繼承','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-050','113-3301',50,'single_choice','甲有乙丙丁三子，乙有一子戊。甲因乙分居而給與新臺幣（下同）150 萬元，因丙出國而給與150 萬 元，因丁結婚而給與150 萬元。乙先甲死亡。甲死亡時，留有300 萬元遺產。甲之遺產應如何分配？','戊50 萬元、丙200 萬元、丁50 萬元','戊100 萬元、丙100 萬元、丁100 萬元','戊150 萬元、丙150 萬元、丁0 元','戊200 萬元、丙50 萬元、丁50 萬元','民法','親屬繼承','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-051','113-3301',51,'single_choice','關於民事訴訟法與憲法之關係，下列敘述，何者錯誤？','民事訴訟制度應避免突襲裁判，並確立當事人之程序主體地位','法官迴避制度具有確保當事人公正程序請求權之意義','三級三審制度係憲法上司法救濟請求權之要素，不容當事人處分或立法簡化','法律安定性及個案正義，均為民事訴訟法建構制度時之基本信念，但因二者偶而會發生衝突，故有 權衡之必要','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-3301-052','113-3301',52,'single_choice','甲居住於臺中，乙居住於臺北，甲向臺灣臺中地方法院（下稱臺中地院）起訴，請求被告乙返還借款。 甲乙間之借貸契約並無合意管轄法院之約款。乙於接獲法院通知後，前往臺中地院開庭，並提出清償 抗辯。下列敘述，何者錯誤？','臺中地院因被告乙為本案言詞辯論，已取得管轄權','乙於辯論終結前，聲請臺中地院移轉管轄至臺灣臺北地方法院（下稱臺北地院），臺中地院於尚未 辯論終結前，應移轉至臺北地院','如經臺中地院判決後，敗訴之當事人提起上訴，第二審法院不得以管轄錯誤為理由，廢棄原判決','如經臺中地院判決後，當事人均未上訴而確定時，敗訴之一造不得以本件確定判決無管轄權為由， 提起再審之訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-3301-053','113-3301',53,'single_choice','關於普通法院之審判權，下列敘述，何者錯誤？','當事人未於事實審爭執普通法院欠缺審判權者，仍得據以為上訴第三審法院之理由','普通法院就行政法院移送之訴訟認無審判權者，如當事人合意願由普通法院審判，即應審判之','普通法院認受理之事件為行政爭訟事件而無審判權者，應依職權將訴訟移送至該管行政法院','普通法院就私法關係所生之爭議，有審判權','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-3301-054','113-3301',54,'single_choice','原告甲列乙、丙、丁、戊等四人為被告，起訴聲明求為判決乙應將A 地中A1 部分、丙應將A2 部分、 丁應將A3 部分、戊應將A4 部分分別返還予甲，主張事實及理由略為：A 地為甲所有，其中A1 部分 遭乙、A2 部分遭丙、A3 部分遭丁、A4 部分遭戊分別無權占有，均拒不返還，為此，本於所有物返還 請求權起訴等旨。此訴訟經第一審判決甲全部勝訴，下列敘述，何者正確？','乙提起上訴，主張：甲曾同意將A 地之A1、A2、A3、A4 分別出租予乙、丙、丁、戊等四人，故有 使用土地之正當權利等語。受理乙上訴之上級審法院應將未曾提起上訴之丙、丁及戊等人均列為上 訴人進行本案審理','乙提起上訴後，丙受原判決之送達而逾上訴期間未表明上訴時，其尚得向受理乙上訴之第二審法院 追加為上訴人（當事人）','乙及丙均提起上訴，丙於上訴審程序承認甲就A 地有所有權之事實後，乙不得再就此事實加以爭執','乙及丙均提起上訴，各主張自己基於租賃權使用系爭地，為此乙聲請訊問證人X，法院就訊問X 之 結果，經兩造辯論後，得作為認定丙有租賃權之基礎','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-3301-055','113-3301',55,'single_choice','甲為英屬開曼群島之外國法人，主張乙侵害其商標權，於臺灣臺北地方法院提起侵權行為損害賠償訴 訟，請求乙賠償新臺幣500 萬元。於第一次言詞辯論期日，乙抗辯甲應提供訴訟費用之擔保。下列敘 述，何者錯誤？','法院應先調查甲在我國境內有無事務所及營業所，或有無足以賠償訴訟費用之資產','於法院尚未對訴訟費用擔保為裁定或准訴訟費用擔保而原告未提供擔保前，被告得拒絕本案辯論','法院定擔保額時，應將第一、二、三審之裁判費及各審之律師費計入','法院命供訴訟費用擔保之裁定，得為抗告','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-3301-056','113-3301',56,'single_choice','關於一造辯論判決，下列敘述，何者正確？','得聲請一造辯論而為判決者，以原告為限，被告不得為之','法院不得依職權由一造辯論而為判決','當事人有正當理由不到場時，法院不得依他造聲請由其一造辯論而為判決','於訴訟標的須合一確定之共同訴訟，言詞辯論期日共同訴訟中一人到場，他造全體不到場時，雖經 到場者聲請，法院不得為一造辯論之判決','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-3301-057','113-3301',57,'single_choice','甲、乙、丙三人共有A 地，甲列乙、丙為被告，起訴請求法院裁判分割該地。下列敘述，何者錯誤？','法院裁判准分割A 地時，不受原告訴之聲明就如何分割A 地所表明之分割方法所拘束，但此項表 明可資以促使本案審理集中化','在乙抗辯共有人間已有分割之協議時，甲得追加請求判決命乙及丙履行該協議','如乙之應有部分於訴訟繫屬前已讓與丁，則甲之起訴欠缺被告適格','如乙之應有部分於其收受甲之起訴狀後讓與丙，則自丙受讓之時起，乙喪失被告適格','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-3301-058','113-3301',58,'single_choice','下列所示證人之證言或提出之書狀，何者屬於法院不得逕採為認定事實之證據？','以元首為證人，在其所在地經命其具結後詢問所錄取之證言','經兩造同意，證人於法院外以書狀為陳述並將具結結文附於書狀，經公證人認證後，向法院提出','法院通知證人到庭作證，證人因故無法出席，獨自前往公證人面前作成陳述書狀及具結結文向法院 提出','法院於命證人具結後，運用聲音及影像相互傳送之科技設備直接訊問證人所錄取之證言','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-3301-059','113-3301',59,'single_choice','甲列乙為被告，訴請給付租賃A 屋之租金新臺幣（下同）100 萬元，於訴狀送達後，甲擬追加請求法 院判命乙給付買賣B 貨物之價金200 萬元。下列敘述，何者正確？','如甲於第一審程序中追加，兩項請求之基礎事實同一，法院應准許追加','如甲於第一審程序中追加，兩項請求之基礎事實不同一，乙不同意且無擬制同意存在，有礙訴訟終 結時，法院應不許追加','如甲係於第二審程序中追加，兩項請求之基礎事實同一，無須乙同意，法院應准許追加','如甲係於第二審程序中追加，兩項請求之基礎事實不同一，即使乙不同意，法院得以不甚礙乙之防 禦及訴訟終結准許追加','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-3301-060','113-3301',60,'single_choice','甲與乙於某日訂立買賣契約，以甲所有之A 地為標的物，約定以價金新臺幣（下同）200 萬元出賣予 乙，嗣後雙方就該契約已否因一方行使解除權而消滅發生爭執，有意循訴訟程序解決紛爭。關於程序 之選擇，下列敘述，何者錯誤？','甲為原告訴請確認系爭買賣契約所生買賣關係不存在時，得與被告乙合意請求受訴法院適用簡易訴 訟程序為審判','甲起訴請求被告乙給付價金200 萬元時，不得與乙合意請求受訴法院適用小額訴訟程序為審判','乙起訴請求判決命被告甲將A 地所有權移轉登記予乙，經第一審法院以乙之請求無理由判決其敗 訴後，在上訴期間內，如兩造間已合意承認該第一審判決所為事實認定無誤，得合意逕向第三審上訴','甲與乙得合意由甲起訴請求法院判決確認解除權不存在，並於其裁判後逕向第三審上訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-3301-061','113-3301',61,'single_choice','關於訴訟上和解，下列敘述，何者錯誤？','原告欲使被告以外之第三人參與和解，應先將其追加為被告','成立訴訟上和解後，當事人得聲請退還該審級裁判費三分之二','因試行和解或定和解方案，法院得命當事人或法定代理人本人到場','當事人間所成立之訴訟上和解，與確定判決有同一之效力','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-3301-062','113-3301',62,'single_choice','乙本於A 地所有權，訴請甲塗銷A 地所有權移轉登記，主張其與甲訂有買賣A 地契約，並辦畢所有 權移轉登記予甲，惟該買賣契約與物權契約有無效之事由。下列敘述，何者正確？','乙向法院聲請裁定許可為訴訟繫屬事實登記，法院不得准許','如乙起訴合法，法院應依其聲請，裁定許可為訴訟繫屬事實之登記','乙聲請裁定許可訴訟繫屬事實登記時，就本案請求釋明如有不足，法院得命其供相當之擔保後准許之','乙聲請裁定許可訴訟繫屬事實登記時，為避免甲脫產，法院為裁定前，不得使甲有陳述意見之機會','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-3301-063','113-3301',63,'single_choice','當事人於法院通知期日未到場者，下列敘述，何者錯誤？','原告於準備程序期日未到場，而被告拒絕陳述時，視為合意停止訴訟','當事人均未到場，依法視為合意停止訴訟後，法院得依職權續行訴訟','當事人一造未到場時，法院仍得調查證據','小額事件依法進行調解程序者，被告經合法通知無正當理由未到場時，原告得聲請即為訴訟之辯論， 而為一造辯論判決','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-3301-064','113-3301',64,'single_choice','原告甲為被告乙公司之股東，提起確認之訴，請求確認乙公司於民國110 年12 月10 日所召開之董事 會（下稱系爭董事會）確有通過A 決議，並請求確認乙公司於另案刑事訴訟中所提出系爭董事會會議 紀錄遭變造。乙公司於訴訟中就系爭董事會確有通過A 決議一事並不爭執，惟否認有變造系爭董事 會會議紀錄。下列敘述，何者錯誤？','甲請求確認系爭董事會有通過A 決議部分，無確認利益','甲請求確認系爭董事會會議紀錄遭變造部分，非屬確認證書真偽之訴','確認法律關係基礎事實存否之訴，不限於確認現在之法律關係基礎事實存否','如A 決議係解任乙公司之總經理丙，甲不得於訴訟中變更為請求確認乙、丙間之委任關係不存在','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-3301-065','113-3301',65,'single_choice','甲列乙、丙為被告，起訴請求確認乙、丙間買賣關係不存在，關於訴訟中之證據方法，下列敘述，何 者錯誤？','法院得依職權訊問乙、丙，但不得命其具結','甲得聲請法院裁定命乙、丙提出系爭買賣契約原本','甲得聲請法院裁定命第三人仲介公司提出其所保管之系爭買賣契約原本，如仲介公司拒絕，法院得 以裁定命為強制處分','如關於買賣契約條款之解釋有爭執，乙、丙於訴訟中已自行提出買賣契約影本，而拒絕依法院之命 提出原本，法院得依自由心證斷定該影本之證據力','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true)
insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('113-3301-066','113-3301',66,'single_choice','甲對乙提起訴訟後，受訴法院詢問兩造有無調解意願，經兩造陳明願意進行調解程序後，將本件訴訟 移付調解。關於調解程序，下列敘述，何者錯誤？','經移付調解後，訴訟程序停止進行，應待調解之結果而決定有無繼續進行訴訟程序之必要','兩造於調解期間均不到場，如法院認有調解成立之可能，仍得另定調解期日','關於財產權爭議之調解，如經兩造同意，得由調解委員酌定解決事件之調解條款','關於財產權爭議之調解，法院依職權提出解決事件之方案後，須經當事人明示同意，方得認為調解 成立','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-3301-067','113-3301',67,'single_choice','關於簡易訴訟程序，下列敘述，何者錯誤？','原告提起財產權之訴訟，其標的金額為新臺幣（下同）50 萬元者，亦屬於50 萬元以下之財產權訴 訟，法院應適用簡易訴訟程序審理','原告起訴請求確認與被告間就某一面額100 萬元之本票債權不存在之訴，係屬本於票據有所請求而 涉訟，法院應適用簡易訴訟程序審理','產物保險公司代位道路交通事故被害人向加害者請求交通事故損害賠償80 萬元事件，屬於本於道 路交通事故有所請求而涉訟，法院應適用簡易訴訟程序審理','原告於刑事簡易程序第二審提起附帶民事訴訟，刑事庭判決刑事被告有罪後，將附帶民事訴訟移送 同法院民事庭，為適用刑事簡易訴訟程序案件之附帶民事訴訟，經裁定移送民事庭者，民事庭應適 用簡易訴訟程序之第一審程序審理','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-3301-068','113-3301',68,'single_choice','甲、乙分別為經營成衣買賣之供貨、銷售公司，甲起訴請求乙給付貨款新臺幣（下同）5 萬元。下列 敘述，何者錯誤？','法院應先行調解程序，如調解不成立，即適用小額訴訟程序審理','乙於調解期日7 日前經合法通知，無正當理由而未到場，法院得依到場甲之聲請，命即為訴訟之辯 論，並依職權由甲一造辯論而為判決','甲依定型化契約約款向合意管轄法院起訴時，乙得抗辯小額訴訟程序無合意管轄規定之適用','乙對甲反訴請求債務不履行之損害賠償60 萬元，法院應以其反訴不合法，裁定駁回','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-3301-069','113-3301',69,'single_choice','關於在第二審為訴之變更或追加，下列敘述，何者正確？','一律均須得他造之同意，始得為之','將離婚之訴變更為撤銷婚姻之訴，不須經他造同意','追加必須合一確定之原非當事人之人為他造當事人，須得原為他造當事人之人同意，始屬合法','因訴之變更為以新訴取代舊訴，舊訴視為撤回，第二審法院專就新訴為審判，故訴之變更倘不合法， 即應駁回該新訴，無須就舊訴續為審理','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-3301-070','113-3301',70,'single_choice','甲起訴請求法院判命乙給付新臺幣（下同）300 萬元，第一審法院判決命乙給付甲200 萬元，並駁回 甲其餘之訴。甲就其敗訴全部合法提起第二審上訴，乙於第二審程序就其敗訴全部為附帶上訴。下列 敘述，何者錯誤？','甲在第二審程序聲明撤回上訴，若乙不同意，就不生撤回上訴之效力','乙就其敗訴全部曾提起上訴並經撤回後，見甲提起上訴，始在程序進行中，再提附帶上訴，則其上 訴權已因撤回上訴而消滅，附帶上訴不合法，第二審法院應以裁定駁回附帶上訴','乙於逾上訴期間後始在第二審程序提附帶上訴，附帶上訴雖非不合法，惟若甲之上訴經第二審法院 以不合法為由而駁回者，該附帶上訴即失其效力，第二審法院無須為任何裁判','乙於提起附帶上訴後撤回附帶上訴，第二審法院審理後為駁回甲上訴之判決，甲不服上訴，第三審 法院將原判決廢棄發回，乙在第二審更審程序，不得再提起附帶上訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-3301-071','113-3301',71,'single_choice','下列敘述之情形，何者不屬當事人得在第二審法院提出之新攻擊或防禦方法？','在第一審請求承租人給付積欠租金之原告，追加請求自租期屆滿日起至返還租賃物之日止相當於租 金額之損害金','請求履行債務事件之被告於第一審受敗訴判決後，為部分清償，因而抗辯原告之請求在該清償範圍 內為無理由','請求返還借款事件之原告，就曾交付借款一事提出支票乙紙為證，被告否認受借款之交付。第一審 法院未經整理證據上爭點即以原告不能證明有交付借款之事實為由，駁回原告之請求。原告上訴後， 為證明該借款已交付之事實，聲請訊問證人某甲','被告於第一審言詞辯論終結後向原告表明就原告主張之債權為抵銷，並於第二審提出該抵銷之抗辯','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-3301-072','113-3301',72,'single_choice','下列何者之原告，得提起第三審上訴？','原告就第二審駁回其請求離婚及贍養費新臺幣（下同）50 萬元之判決提起上訴','原告就其敗訴之100 萬元部分上訴，被告就其敗訴之200 萬元部分上訴','原告起訴請求拆屋還地時之土地價值經法院核定為90 萬元，並據此繳納一、二審裁判費。於原告 提起第三審上訴日該地價值已升值為180 萬元','原告就敗訴之140 萬元聲明不服，並於上訴第三審之同時擴張請求30 萬元','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-3301-073','113-3301',73,'single_choice','關於第三審上訴之審理，下列敘述，何者正確？','第三審原則上應經言詞辯論，故無關本案請求有無理由之攻擊防禦方法，無須記載於答辯狀','第三審法院在行言詞辯論程序時，宜先曉諭法律上爭點','第三審行言詞辯論時雖得試行和解，但不得使兩造成立訴訟上和解','第二審法院判決廢棄家事法院所為確認收養關係存在之第一審本案判決後，當事人不得對此第二審 判決提起第三審上訴','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-3301-074','113-3301',74,'single_choice','關於再審管轄權，下列敘述，何者正確？','經第二審法院判決確定之事件，當事人對於同一事件之第一審及第二審判決同時聲明不服，提起再 審之訴，專屬原第一審法院管轄','當事人對第二審判決提起上訴，經第三審法院以上訴不合法裁定駁回。當事人以適用法規顯有錯誤 為由，對於第二審判決提起再審之訴，並對第三審裁定聲請再審，專屬原第二審法院合併管轄','當事人對第三審判決以適用法規顯有錯誤為理由，提起再審之訴，專屬該第三審法院管轄','經第三審法院判決確定之事件，當事人對該第二審、第三審判決提起再審之訴，專屬第三審法院合 併管轄','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],11,11,'parsed','pending_manual_review',null,true),
('113-3301-075','113-3301',75,'single_choice','甲基於侵權行為之損害賠償請求權，向某地方法院起訴請求判命被告乙賠償新臺幣800 萬元，並向受 訴法院聲請訴訟救助。受訴法院就訴訟救助聲請部分，裁定予以准許後，乙不服提起抗告。下列敘述， 何者錯誤？','乙於收受准予訴訟救助之裁定後，得於法定期間內提起抗告。但乙如在裁定送達前提起抗告，亦有 效力','乙提起抗告，若未依法繳納抗告裁判費，經原受訴法院定期命其補正而未補正者，原受訴法院得以 裁定駁回其抗告','准予訴訟救助之裁定經宣示後，為裁定之法院應受其羈束，故縱原審法院認為乙之抗告為有理由， 亦不得自行撤銷或變更原裁定','抗告法院認為乙之抗告有理由者，應以裁定廢棄或變更原裁定','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-3301-076','113-3301',76,'single_choice','甲對乙有新臺幣500 萬元之本票債權，乙拒不清償，下列敘述，何者錯誤？','因請求金額過大，甲不得向法院聲請發支付命令','甲提起給付票款訴訟時，應適用簡易訴訟程序','甲聲請法院調解時，法院得逕以裁定駁回','甲得聲請法院裁定本票准予強制執行','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-3301-077','113-3301',77,'single_choice','甲、乙婚姻關係存續中，甲與丙通姦，乙對甲、丙起訴主張甲、丙通姦而請求侵權行為損害賠償。嗣 乙另對甲起訴，以不堪甲同居之虐待及甲通姦為由，請求裁判離婚，並酌定對於甲、乙所生未成年子 女A 之權利義務之行使負擔。下列敘述，何者錯誤？','離婚訴訟應先行家事調解程序，並得經甲、乙、丙合意，將乙對甲、丙之損害賠償訴訟合併於離婚 事件調解','甲、乙若於離婚訴訟中本人親自到場同意離婚，並合意對於A 權利義務之行使負擔由乙任之，且符 合A 之最佳利益，即可以該合意內容成立和解，並載明於和解筆錄','甲在調解程序中自承有通姦的事實，於調解不成立後，法院不得採為離婚訴訟裁判之基礎','乙雖於調解程序中放棄「甲通姦」離婚事由之主張，並就此成立書面協議，於調解不成立後，仍得 於裁判離婚訴訟中主張該離婚事由','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-3301-078','113-3301',78,'single_choice','關於家事事件之審理原則，下列敘述，何者錯誤？','在改定監護人事件，法院不受聲請人表明之監護人選所拘束，此乃職權主義（公權主義）之展現','在確認婚姻無效事件，法院不受當事人自認關於婚姻有效或無效之事實所拘束，此乃職權探知主義 之展現','在認可收養事件，當事人於請求法院裁判前，應經法院調解，此乃調解前置及促成合意原則之展現','離婚事件與酌定未成年子女親權事件合併請求，此乃統合處理原則之展現','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-3301-079','113-3301',79,'single_choice','印度籍之甲夫與臺灣籍之乙妻結婚，婚後生有未成年子丙，全家居住於甲夫之工作地點新竹，後甲、 乙不合，甲離開臺灣前往菲律賓工作，之後失去連絡，乙攜丙回娘家屏東居住。關於審理程序，下列 敘述，何者錯誤？','乙以甲離家失聯，長期未同居，有重大事由請求裁判離婚，有關我國法院程序之規定，應適用中華 民國法律','乙請求甲償還先前代甲墊付丙之扶養費事件，應另行起訴，不得與乙對甲之離婚事件合併請求','丙請求甲給付扶養費事件，屏東地方法院有管轄權','在乙對甲請求裁判離婚之訴訟繫屬中，乙得合併請求對丙權利義務之行使負擔由乙任之','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-3301-080','113-3301',80,'single_choice','甲夫、乙妻有未成年之婚生子丙，乙婚前另與丁男交往，甲死亡後，其母戊認為丙非甲之子，提起確 認親子關係不存在訴訟。下列敘述，何者正確？','戊應以乙、丙、丁為共同被告，當事人始適格','如丙受婚生子女推定，則戊所提訴訟為無理由','為監督法官之審理，此類訴訟所有民眾皆可旁聽','受訴法院得命被告乙本人到場，如乙無正當理由不到場，法院得裁罰，並命拘提','民事訴訟法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],12,12,'parsed','pending_manual_review',null,true),
('113-4301-001','113-4301',1,'single_choice','依公司法第22 條之1 規定，公司應每年定期以電子方式，將內部人之資料申報至臺灣集中保管結算 所建置維護之資訊平臺，下列何者非須申報之內部人？','董事、監察人、經理人','董事、監察人、經理人之配偶、未成年子女及為其持有公司股票者','持有已發行股份總數超過10%之股東','出資超過資本總額10%之股東','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-4301-002','113-4301',2,'single_choice','依公司法中有關公司登記之規定，下列敘述何者正確？','公司申請設立登記之資本額，應經會計師查核簽證，公司應於申請設立登記時或設立登記後3 個月 內，檢送經會計師查核簽證之文件','公司應收之股款，股東並未實際繳納，而以申請文件表明收足，公司負責人經法院判決有罪確定。 在此判決確定前，公司縱已完成補正，中央主管機關因系爭確定判決仍應撤銷或廢止公司登記','公司負責人犯偽造文書印文罪章之罪辦理增資登記，經法院判決有罪確定後，利害關係人得申請中 央主管機關撤銷其增資登記','公司申請變更登記之資本額，無須會計師查核簽證','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-4301-003','113-4301',3,'single_choice','X 公司持有Y 公司已發行股份總數5%的股份，擬參與Y 公司經營，正評估以X 公司名義或由X 公 司代表人擔任董事之利弊。依公司法規定，下列敘述何者錯誤？','如X 公司擔任Y 公司董事，其應指定自然人代表行使職務，而在董事任期內，X 公司得隨時改派 代表人補足其任期','如X 公司代表人甲及乙二人同時當選為Y 公司董事時，在董事任期內，X 公司得改派丁及戊補足 其任期','如Y 公司為公開發行股票之公司，X 公司代表人甲擔任Y 公司董事，X 公司在甲之董事任期內將 Y 公司持股全數轉讓給他人時，甲即喪失其董事資格','如Y 公司為公開發行股票之公司，X 公司在擔任Y 公司董事時，將Y 公司持股全數設質，X 公司 即喪失其董事資格','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-4301-004','113-4301',4,'single_choice','A 有限公司（下稱A 公司）本身進行金融科技產業，欲擴大公司規模，故欲尋覓合作對象，以追求企 業合併綜效。下列有關有限公司合併之敘述，何者錯誤？','A 公司須經全體股東同意，方可與B 有限公司合併','若A 公司欲與C 股份有限公司進行存續合併，則存續公司必須為C 股份有限公司','A 公司決議與D 有限公司合併後，則應通知各債權人，並指定30 日以上期限，聲明債權人得於期 限內提出異議','若A 公司決議與E 有限公司合併卻漏未通知債權人，則不得以其合併對抗債權人','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-4301-005','113-4301',5,'single_choice','關於有限公司股東權限之敘述，下列何者正確？','股東按出資多寡比例分配表決權，但得以章程訂定，不論出資多寡，每一股東均有一表決權','有限公司的股東有自由移轉其出資額之權利','在有限公司增資情況，如股東同意該議案，將負等比例承購義務','會計年度終了之會計表冊承認，應經股東表決權過半數之同意','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('113-4301-006','113-4301',6,'single_choice','A 有限公司（下稱A 公司）有甲、乙、丙、丁及戊共5 位股東，各出資新臺幣100 萬元，章程規定 設置董事3 人，董事長1 人，由甲、乙、丙當選董事，下列關於A 公司董事、董事長之敘述，何者 正確？','A 公司之董事長應經股東表決權三分之二以上之同意選任之','A 公司董事長應經董事全體同意選任之','A 公司董事，非有特約，不得向公司請求報酬','A 公司若有董事為自己或他人為與公司同類業務之行為，應對全體董事說明其行為之重要內容，並 經董事過半數之同意','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-4301-007','113-4301',7,'single_choice','關於公司虧損時所得採取行為之相關規範，下列敘述何者錯誤？','董事會為彌補公司虧損，提出減少資本議案，應於股東會開會30 日前交監察人查核後，提請股東 會決議','公司虧損達實收資本額三分之二時，董事會應於最近一次股東會報告','公司資產顯有不足抵償其所負債務時，除得進入重整程序外，董事會應即聲請宣告破產','公司如最近連續二年有虧損者，原則上不得公開發行新股','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-4301-008','113-4301',8,'single_choice','A 上市公司（下稱A 公司）持有B 公司已發行有表決權之股份總數51%，B 公司持有C 公司已發行 有表決權之股份總數49%，並指派代表人當選C 公司過半數之董事，A 公司對C 公司則無持股，C 公 司對A 公司及B 公司各持有已發行有表決權之股份總數1%，下列關於收買股份或有無表決權之敘 述，依公司法規定及最高法院之見解，何者正確？','B 公司得收買A 公司之股份','C 公司不得收買B 公司之股份','C 公司持有A 公司之1%股份，有表決權','C 公司持有B 公司之1%股份，無表決權','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-4301-009','113-4301',9,'single_choice','關於公司法第214 條之股東代表訴訟制度，下列敘述何者正確？','欲行使本條之少數股東權，須為繼續6 個月以上，持有已發行股份總數百分之三以上之股東','符合本條規定之股東提起訴訟時，為避免濫訴，應以書面先向董事會請求','為求減低負擔，股東提起代表訴訟時，其裁判費超過新臺幣100 萬元部分免收','股東提起代表訴訟時，法院得依聲請為原告選任律師為訴訟代理人','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-4301-010','113-4301',10,'single_choice','關於公司法第235 條之1 股份有限公司員工酬勞分派之規定及其實務見解，下列敘述何者錯誤？','計算員工、董監事酬勞時，應以當年度獲利扣除累積虧損後，再就餘額計算員工、董監事酬勞','公司應於章程訂明以當年度獲利狀況之定額或比率，分派員工酬勞。所謂比率須為固定比例（例如 1%），不得為一定區間（例如1-3%）','員工酬勞得以發放現金或股票為之，經董事會特別決議並報告股東會即可','公司董事長兼任員工時，可基於員工身分受員工酬勞之分派','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-4301-011','113-4301',11,'single_choice','關於閉鎖性股份有限公司，下列敘述何者錯誤？','股東人數不得超過五十人，亦不得為公開發行股票公司','不得分次發行股份','公司可於證券主管機關許可之證券商經營之股權群眾募資平臺募資','公司股份轉讓之限制應於章程載明','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-4301-012','113-4301',12,'single_choice','股票未公開發行之A 股份有限公司擁有股東約50 人，下列對於該公司董事會與董事之相關敘述，何 者錯誤？','該公司得依章程規定不設董事會','董事選舉必須採累積投票制','董事選舉必須採候選人提名制','董事缺額達三分之一時，應於30 日內召開股東臨時會補選','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('113-4301-013','113-4301',13,'single_choice','甲公司董事會決議向其大股東A 借款8,000 萬元，年息百分之十，但目前銀行之企業貸款年息約百分 之三。甲公司之章程明訂，公司對外借款超過5,000 萬元應經過股東會同意。甲公司監察人B 及持股 已達2 年之股東C，對董事會自行決定且未得到股東會同意，便自行借款的情事均表示不滿，欲制止 董事會，下列敘述何者正確？','若股東C 未持有甲公司已發行有表決權股份總數之百分之一以上股份，不得自行行使制止請求權','若股東C 未持股百分之一以上，應先請求監察人B 制止董事會；如監察人B 無正當理由不行使， 始得由股東C 自行制止之','因為本案已經董事會討論並通過，故監察人B、股東C 二人皆不得行使制止請求權','監察人B、股東C 二人均能立即行使制止請求權，並無何者須優先行使的次序要求','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-4301-014','113-4301',14,'single_choice','A 股份有限公司（下稱A 公司）為一從事食品加工的非公開發行公司，該公司章程規定公司股份總數 為100 萬股，全數均為普通股，並以每股票面金額新臺幣10 元全數發行。目前A 公司之實收資本額 為新臺幣1,000 萬元，其中X 股份有限公司（下稱X 公司）持有A 公司股份35 萬股，X 公司之從屬 公司Y 股份有限公司亦持有A 公司股份25 萬股。其後，A 公司為擴大公司規模，打算再發行50 萬 普通股。新股發行除依法保留總數百分之十的股份由A 公司員工承購外，其餘全數由原股東按其原 有持股比例認購完畢。依公司法規定，下列敘述何者正確？','A 公司此次發行新股只要董事會同意即可，無須經股東會同意','X 公司於此次發行新股僅能以現金出資方式認購，不得以A 公司事業所需之財產為出資','A 公司此次發行新股保留由原股東認購者，A 公司得限制其在2 年內不得轉讓','A 公司不論增資發行新股前後，X 公司與A 公司之關係屬於控制公司與從屬公司之關係','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-4301-015','113-4301',15,'single_choice','A 醫院轉投資B 有限公司、C 股份有限公司、D 商號、E 有限合夥，均取得有表決權之股份或出資額 超過半數。此五家組織中，有幾家彼此間可能構成公司法上之關係企業？','2','3','4','5','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-4301-016','113-4301',16,'single_choice','下列關於人壽保險契約之相關規定敘述，何者錯誤？','保險費到期未交付者，除契約另有訂定外，經催告到達後屆30 日仍不交付時，保險契約之效力停止','被保險人年齡不實，而其真實年齡已超過保險人所定保險年齡限度者，其契約無效，保險人應退還 所繳交保險費','即使契約中已指定受益人，除要保人聲明放棄處分權者外，仍得以契約或遺囑變更之','保險費付足二年以上者，要保人方得以保險契約為質，向保險人借款','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-4301-017','113-4301',17,'single_choice','下列關於保險法涉及保險契約訂立之規定，何者錯誤？','人身保險不得為指示式或無記名式','保險契約由代理人訂立者，適用民法之相關規定即可，無庸再行載明代訂之意旨','保險契約由合夥人或共有人中之一人或數人訂立，而其利益及於全體合夥人或共有人者，應載明為 全體合夥人或共有人訂立之意旨','保險人得約定保險標的物之一部份，應由要保人自行負擔由危險而生之損失。有此約定時，要保人 不得將未經保險之部份，另向他保險人訂立保險契約','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-4301-018','113-4301',18,'single_choice','甲以其即將大學畢業之子乙為被保險人向A 壽險公司（下稱A 公司）投保傷害保險，保險契約條款 約定：「被保險人職業變更時應書面通知保險人；未通知者，保險契約自動解除」。乙畢業後參加政府 所舉辦的短期電工技職訓練班，未通知保險人A 公司，訓練期間與其他學員外出旅遊時，巧遇旅館失 火而死亡。試問保險人A 公司主張不負保險責任，有無理由？','有理由，被保險人未通知，契約自動解除','有理由，被保險人未通知，保險人仍須行使解除權，契約方解除','無理由，應通知而未通知，保險人僅得請求損害賠償，仍負給付保險金之責','無理由，損害之發生不影響保險人之負擔，保險人仍應全額賠償','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('113-4301-019','113-4301',19,'single_choice','甲以其所有之房屋（廠房兼住家）向A 產險公司（下稱A 公司）投保火災保險500 萬元，並以配偶 乙為被保險人向B 壽險公司（下稱B 公司）投保意外保險1,000 萬元。今甲之受僱人丙因工資報酬問 題與甲產生糾紛，遂故意縱火，導致廠房全損及乙罹難火場。A 公司、B 公司分別為保險理賠後，對 丙主張保險代位求償，有無理由？','A 公司、B 公司均有理由','A 公司、B 公司均無理由','A 公司有理由，B 公司無理由','A 公司無理由，B 公司有理由','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-4301-020','113-4301',20,'single_choice','甲於民國112 年（下同）6 月1 日參加大學同學會，經昔日同窗乙招攬，詳細說明保單相關內容後， 決定以自己為被保險人向A 保險公司（下稱A 公司）投保人壽保險契約，乙於次日將甲填載完成之 要保書回傳A 公司完成要保程序，並於同日印出繳費單，甲於6 月5 日於超商繳費完成。甲於6 月 10 日收到A 公司所寄發核保通過簡訊，A 公司並於6 月15 日寄出保險單。然甲已於6 月12 日因意 外事故死亡。下列敘述何者正確？','依保險法規定，保險契約應以保險單或暫保單為之。甲死亡時保險契約尚未成立生效，保險人無需 為保險給付','保險契約為要物契約，甲於6 月5 日完成繳費，契約成立生效，保險人應為保險給付','乙為保險公司業務員，為A 公司向甲招攬，甲完成要保書回傳並繳費，雙方意思表示合致，契約於 6 月5 日成立生效，保險人應理賠','保險契約為不要式不要物契約，保險人核保時，雙方意思表示已經合致，契約成立生效，保險人應 依約給付','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-4301-021','113-4301',21,'single_choice','疏浚業者甲以其所有的一艘老抽砂船向產險業者乙投保船舶保險，該船市價及保險金額同為3,000 萬 元，因船舶老舊且非航行用船，保單特別約定「保險期間船舶航行不得超出臺北港」並約定適用中華 民國法。保險期間，甲另外承攬澎湖馬公港疏浚工程，抽砂船駛往馬公港途中於臺中港外海擱淺受損， 甲耗費2,000 萬元進行船舶救助，另船舶維修費2,500 萬元。如依實務判決見解，本案乙保險人責任 為何？','主張甲違反特約條款，自違反之時起，保單即刻失效，乙無須理賠','主張甲違反特約條款，乙如於一個月內解除契約，即無須理賠','特約條款顯失公平，應屬無效，乙應賠償保險金額3,000 萬元','特約條款顯失公平，應屬無效，並依保險法第33 條規定，乙應賠償4,500 萬元','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-4301-022','113-4301',22,'single_choice','A 遊樂場向B 保險公司（下稱B 公司）投保責任保險。甲於A 遊樂場遊玩時，因設施故障而受傷， 事故後1 個月，A 遊樂場破產結束營業。甲求償無門，乃依保險法第94 條向B 公司為直接請求損害 賠償。B 公司主張A 遊樂場未繳保費且違反遊樂設施定期保養特約條款規定，於事故發生後2 週已解 除契約，自不負理賠責任。下列關於B 公司之主張有無理由之敘述，何者正確？','有理由，因保險契約已經解除，保險人不負理賠責任','無理由，保險契約效力屬B 保險公司與A 被保險人間之內部關係，不影響受害第三人甲對B 保險 人之直接請求權','有理由，因A 遊樂場未賠付甲之前，損失尚未確實發生，B 公司本無須負責','無理由，B 公司仍應理賠，理賠後再向已破產的A 遊樂場為主張','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-4301-023','113-4301',23,'single_choice','依我國保險法之規定，保險業之同業公會為會員之健全經營及維護同業之聲譽，應辦理相關事項。下 列敘述何者錯誤？','訂定自律規範並請專家審核後即可提供會員遵循','就會員所經營業務發生紛爭時為必要協調','辦理保險主管機關委託辦理之事項','訂立實務作業規定時得要求會員提供相關資料','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-4301-024','113-4301',24,'single_choice','關於未來事項之特約條款，在訂約地為不合法而未履行者，保險契約之效力為何？','因客觀不能而契約無效','不拘束保險人','依然有效','不拘束被保險人','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('113-4301-025','113-4301',25,'single_choice','下列有關保險代理人、保險經紀人與公證人之敘述，何者錯誤？','保險經紀人應以善良管理人之注意義務，為被保險人洽訂保險契約或提供相關服務，並負忠實義務','兼有保險代理人、經紀人、公證人資格者，得同時申領執業證照，但保險代理人與經紀人應擇一申領','銀行得經主管機關許可擇一兼營保險代理人或保險經紀人業務','保險經紀人應經主管機關許可，繳存保證金並投保責任保險與保證保險，領有執業證照後，始得經 營或執行業務','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-026','113-4301',26,'single_choice','甲簽發發票日為某年5 月1 日，到期日為同年10 月1 日，面額20 萬元之本票一張交付乙，乙將本票 背書交付丙，丙背書交付丁。如乙於該票據背面簽名旁記載免作拒絕證書，丁於同年10 月3 日請求 甲付款，遭甲拒絕，丁遲至次年10 月2 日始對乙追索，乙對丁有無抗辯事由？','乙對丁有抗辯事由，因追索權時效至次年9 月30 日止','乙對丁有抗辯事由，因追索權時效至次年10 月1 日止','乙對丁無抗辯事由，因追索權時效至次年10 月3 日止','乙對丁有抗辯事由，因丁未遵期為付款提示','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-027','113-4301',27,'single_choice','甲簽發本票一張予乙，以清償所欠貨款新臺幣（下同）10 萬元，然於簽發之際錯看收據上所載數字， 誤填金額為16 萬元。乙於票據到期前將該票背書轉讓予善意之丙，購買丙市價約15 萬元之設備，該 票到期後，丙持以向甲請求付款，下列敘述何者正確？','該票據因金額誤載而無效，甲無須付款','甲可主張該票據所欲清償之債務為10 萬元，而得僅支付10 萬元，就剩餘之6 萬元，丙應向乙請求','因票載金額與實際交易不符，若甲可證明實際債權數額僅10 萬元，則丙僅得請求10 萬元','票載金額為16 萬元，則甲應支付16 萬元','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-028','113-4301',28,'single_choice','甲未經乙之授權，以乙之名義簽發受款人為丙之本票，丙所執之本票被丁所盜，其後丁偽造丙之簽名 轉讓予戊，戊再背書轉讓予善意不知情且有給付對價之己。若己到期不獲付款時，得向何人行使追 索權？','甲','乙','丁','戊','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-029','113-4301',29,'single_choice','乙執有甲簽發之記名匯票，票載付款人為丙。下列何種情況，乙不得於到期日前行使追索權？','丙拒絕承兌','甲死亡','丙受破產宣告','丙行蹤不明，無從為承兌之提示','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-030','113-4301',30,'single_choice','甲因協助A 公司介紹一筆生意而可獲得A 公司給付之佣金，甲擬以由A 公司擔任甲簽發匯票之付款 人方式獲得該佣金，為保證將來A 公司會承兌該票據，A 公司與甲並簽訂書面之契約。甲後來即簽發 一紙以A 公司為付款人之匯票予乙，並將A 公司承諾之事告知乙，乙將該匯票背書轉讓予丙，惟乙 之背書附註該背書須待A 公司履行承兌之承諾始生效力，丙於到期日持匯票向A 公司請求付款，A 公司稱因甲所介紹之生意因故未成交，所以拒絕付款，丙得向何人請求票款？','A 公司、甲、乙','A 公司、甲','A 公司、乙','甲、乙','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-031','113-4301',31,'single_choice','甲與乙為姐妹，為盡孝道扶養行動不方便之母親丙，決定在臺北市購買一間位於一樓之公寓供丙居住。 兩人向銀行貸款時，共同簽發本票並經丙背書予銀行。因房貸之繳款不正常，銀行遂欲以本票行使追 索權，此時乙已因病猝逝，財產由其子丁單獨繼承。依據司法實務之見解，得對何人聲請法院裁定後 強制執行？','僅甲','僅甲丙','僅甲丁','甲丙丁','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-032','113-4301',32,'single_choice','關於本票之背書，下列何種行為，非票據法所許？','以委任取款之目的而為背書','執票人將背書塗銷','背書人記載預備付款人','背書人於票上為禁止轉讓之記載','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-033','113-4301',33,'single_choice','甲於民國109 年7 月1 日簽發記名支票一紙予乙，金額為新臺幣100 萬元，發票地與付款地均為臺南 市，匆忙間，甲漏未記載發票日。下列關於該支票之敘述，何者正確？','以實際發票日為發票日','以乙提示付款日為發票日','該支票視為見票即付','該支票無效','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('113-4301-034','113-4301',34,'single_choice','支票之發票人在下列何期限內，不得撤銷付款之委託？','發票日後3 年內','發行滿1 年後起2 年內','發行滿1 年以前','提示期限內','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-035','113-4301',35,'single_choice','依票據法之規定，下列有關支票之敘述，何者正確？','支票在票載發票日前，執票人為付款之提示，付款人應於見票時無條件付款','支票發票人應照支票文義擔保支票付款，其付款責任與匯票承兌人相同','支票發票地與付款地均為新北市，如發票日後七日執票人不為付款之提示，對於發票人以外之前手， 喪失追索權','支票、匯票、本票發票時，發票日及到期日均為絕對必要記載事項','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-036','113-4301',36,'single_choice','A 股份有限公司（下稱A 公司）為一家從事食品加工之上市公司，並依法設置審計委員會。最近，A 公司擬召開審計委員會，討論年度財務報告等事宜。依證券交易法之規定，下列敘述何者錯誤？','A 公司因已設置審計委員會，所以無須再設置監察人','A 公司審計委員會得決議請公司相關部門經理人員、內部稽核人員、會計師、法律顧問或其他人員 列席會議及提供相關必要之資訊。但討論及表決時應離席','審計委員會之召集，應載明召集事由，於三日前通知委員會各獨立董事成員。但有緊急情事者，不 在此限','A 公司如有正當理由致審計委員會無法召開時，年度財務報告等事項應以全體董事三分之二以上 同意行之。但年度財務報告事項仍應由獨立董事成員出具同意意見','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-037','113-4301',37,'single_choice','A 公司為一家從事醫療器材製造的上市公司，該公司設有薪資報酬委員會。甲最近剛被選任為A 公 司薪資報酬委員會成員，由於甲是首次擔任薪資報酬委員會成員，因此想要了解下列有關薪資報酬委 員會之敘述，何者錯誤？','薪資報酬委員會成員由董事會決議委任之，其人數不得少於三人','薪資報酬委員會得經決議，委任律師、會計師或其他專業人員，就行使職權有關之事項為必要之查 核或提供諮詢，其費用由公司負擔','A 公司董事會通過之薪資報酬如優於薪資報酬委員會之建議，除應就差異情形及原因於董事會議 事錄載明外，並應於董事會通過之即日起算二日內於主管機關指定之資訊申報網站辦理公告申報','薪資報酬委員會應至少每年召開四次，並於薪資報酬委員會組織規程中訂明之','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-038','113-4301',38,'single_choice','甲為A 上市公司（下稱A 公司）持股超過百分之十的大股東。若甲所持有的A 公司股票有所變動時， 其應於次月幾日以前將上月份持有股數變動之情形，向公司申報？公司應於每月幾日以前，彙總向主 管機關申報？','1 日；10 日','5 日；10 日','5 日；15 日','10 日；15 日','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-039','113-4301',39,'single_choice','股票上市之A 公司有法定盈餘公積新臺幣（下同）5 億元，保留盈餘1 億元，發行股份溢價及已實現 之資本公積2 億元，A 公司擬買回股份，依證券交易法之規定，其買回總金額之上限為何？','3 億元','6 億元','7 億元','8 億元','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-040','113-4301',40,'single_choice','公開發行公司募集無擔保轉換公司債，依證券交易法令，原則上其額度限制為何？','不得逾全部資產減去全部負債餘額之50%','不得逾全部資產減去全部負債之餘額','不得逾全部資產減去全部負債餘額之200%','不得逾全部資產減去全部負債餘額之400%','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-041','113-4301',41,'single_choice','依證券交易法發行股票公司之董事、監察人、經理人或持有公司股份超過股份總額10%之股東，依證 券交易法之規定對其股票轉讓之限制，下列敘述何者錯誤？','向主管機關申報生效後，得向非特定人為之','依主管機關所定持有期間及每一交易日得轉讓數量比例，於向主管機關申報之日起3 日後，得向符 合主管機關所定條件之特定人為轉讓','於向主管機關申報之日起3 日內，向符合主管機關所定條件之特定人為之','該股票轉讓方式之限制，亦適用董事之配偶與未成年子女','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('113-4301-042','113-4301',42,'single_choice','依據證券交易法第22 條第3 項及「發行人募集與發行有價證券處理準則」之規定，下列何者為公開 招募？','發起人於公司成立前，對非特定人招募股票之行為','發行公司於發行前，對非特定人招募股票之行為','有價證券持有人為出售其所持有之股票，而對非特定人招募之行為','公開發行公司對特定人招募股票之行為','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-4301-043','113-4301',43,'single_choice','下列何者為證券交易法所稱之發行人？','A 上市公司之總經理甲','以發起設立方式設立B 股份有限公司之發起人乙','募集發行新股之C 股份有限公司','募集發行新股之D 股份有限公司之董事長丙','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-4301-044','113-4301',44,'single_choice','A 公司為一家生產車用電池的上市公司，甲為該公司的獨立董事。近期，A 公司擬討論內部稽核主管 之任免事宜。依證券交易法之規定，下列敘述何者錯誤？','A 公司所設置之獨立董事，人數不得少於三人','甲在獨立董事任期中若轉讓超過選任當時所持有之A 公司股份數額二分之一時，其獨立董事當然 解任','A 公司獨立董事均解任時，公司應自事實發生之日起六十日內，召開股東臨時會補選之','如有正當理由致審計委員會無法召開時，內部稽核主管之任免應以全體董事三分之二以上同意行之','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-4301-045','113-4301',45,'single_choice','A 上市公司（下稱A 公司）總經理甲於今年3 月初買進自家公司上市股票100 張，並於同年5 月中 將其全數賣出，共獲利新臺幣200 萬元。A 公司的股東乙認為甲的行為違反證券交易法短線交易之規 定，公司應積極主張其權利。下列敘述何者錯誤？','A 公司應請求甲將其利益歸於公司，此一請求權自獲得利益之日起1 年間不行使而消滅','A 公司不行使歸入權時，不限持股多寡，任何股東皆得以30 日之限期，請求董事行使之；逾期不 行使時，請求之股東得為公司行使此一請求權','董事不為公司行使歸入權以致A 公司受損害時，對公司負連帶賠償之責','甲之行為並無刑事責任','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-4301-046','113-4301',46,'single_choice','甲執命乙給付金錢之確定判決，聲請強制執行乙對A 地所有權之應有部分；乙之債權人丙就該應有 部分有抵押權，然未聲明參與分配或聲請強制執行；丁為A 地共有人，乙之承租人戊於查封前已占用 A 地。下列何種情形不得依強制執行法第12 條規定聲請或聲明異議？','執行法院定期112 年8 月15 日第一次拍賣，拍賣公告記載「拍定後點交」，戊以拍賣公告記載錯誤 為由，聲請更正記載為「拍定後不點交」','執行法院定期112 年8 月10 日第一次拍賣，拍賣公告於同年7 月29 日揭示在法院公告欄，乙以執 行法院公告時間距離拍賣期日不足法定最短天數為由聲明異議','A 地應有部分拍定收足價金後，執行法院逕行核發權利移轉證書予拍定人，丁以其未獲通知是否 優先承買為由聲明異議','A 地應有部分拍定收足價金後，執行法院作成分配表定期113 年2 月5 日分配，並於同年月1 日 將分配表繕本送達丙，丙以送達時間距離分配期日不足法定最短天數為由聲明異議','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-4301-047','113-4301',47,'single_choice','有關執行名義之種類，下列敘述，何者正確？','我國法院撤銷暴利行為之判決確定者，得為執行名義','我國法院經宣告假執行之租金給付判決，遭上級審廢棄者，仍得為執行名義','我國公證人就一定數額之違約金債務載明應逕受強制執行之公證書，得為執行名義','日本法院之貨款給付判決確定者，得逕為執行名義','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('113-4301-048','113-4301',48,'single_choice','甲於民國（下同）112 年12 月12 日持乙簽發發票日109 年7 月7 日，面額新臺幣200 萬元之支票， 聲請法院對乙核發支付命令獲准，嗣於113 年3 月4 日持該支付命令聲請對乙為強制執行。下列敘述， 何者正確？','倘甲之債權經執行後未獲足額清償，得依強制執行法第27 條規定，聲請執行法院核發債權憑證','乙抗辯甲之票款給付請求權已罹於消滅時效期間，並於甲聲請支付命令前已拒絕給付票款，得依強 制執行法第14 條第1 項規定，於強制執行程序終結前，提起債務人異議之訴，以排除強制執行程序','乙提起債務人異議之訴後，受訴法院應依強制執行法第18 條第2 項規定，以職權裁定乙不須供擔 保而停止強制執行','基於支付命令之即時確定，甲聲請強制執行不須檢附支付命令之確定證明書','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-4301-049','113-4301',49,'single_choice','甲對乙有貨款債權新臺幣（下同）500 萬元，取得確定勝訴判決後，聲請法院強制執行乙所有之市價 1,000 萬元A 地。該地業經乙設定最高限額700 萬元抵押權予丙，以擔保丙對乙尚未屆清償期之借款 債權。下列敘述，何者錯誤？','丙無執行名義，且未聲明參與分配，執行法院仍應通知丙參與分配','丙為保護其期限利益，得拒絕參與分配，而主張拍定後不得塗銷其抵押權設定登記','丙於A 地拍定後始以500 萬元抵押借款債權聲明參與分配，執行法院仍應將丙申報之債權金額列 入分配，並得優先受償','執行法院通知丙參與分配，丙未聲明參與分配，執行法院仍應將丙之700 萬元債權金額列入分配， 並得優先受償','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-4301-050','113-4301',50,'single_choice','有關動產之拍賣與不動產之拍賣，下列敘述，何者正確？','拍定人就拍賣物皆無物之瑕疵擔保請求權','所定底價皆應記載於拍賣公告','皆以投標方式為之','皆須預定拍賣物之底價','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-4301-051','113-4301',51,'single_choice','執行法院依債權人甲之聲請，實現其金錢債權新臺幣（下同）100 萬元，就債務人乙對第三債務人丙 之金錢債權50 萬元發扣押命令，並就乙之不動產為查封後，乙之債權人丁就其金錢債權100 萬元聲 明參與分配，執行法院逕就乙對丙之債權發移轉命令，將該金錢債權移轉予甲。關於丁之救濟，下列 敘述，何者正確？','上開執行程序於移轉命令核發時已告終結，丁無從聲明異議，關於丁之權利受損已無法救濟','因不動產執行程序尚在進行中，故丁仍得聲明異議，聲請執行法院撤銷該移轉命令','丁得對甲提起不當得利之訴訟，請求返還其原應受分配額之利益','執行法院應依職權撤銷該移轉命令','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-4301-052','113-4301',52,'single_choice','債權人甲訴請債務人乙交付A 上市公司股票100 張，獲勝訴判決確定後，持該判決聲請執行法院對 乙為強制執行，乙除B 土地外，已無其他財產。下列敘述，何者正確？','執行法院應適用對於不動產執行之規定，查封拍賣B 土地，於A 上市公司股票100 張之市價範圍 內，將執行所得分配予甲，由甲在公開市場上自行購買100 張A 上市公司股票','乙就交付A 上市公司股票100 張陷於給付不能，甲以不能之給付為執行標的，執行法院應裁定駁 回甲之強制執行聲請','執行法院應命乙自動履行，如不依限履行，得估算代履行費用，以裁定命乙支付。乙不支付，甲得 以此裁定為執行名義，聲請執行法院查封拍賣B 土地，以執行所得支付代履行費用','執行法院應定期命乙交付100 張A 上市公司股票予甲，逾期不履行，得處新臺幣3 萬元以上30 萬 元以下之怠金，經再次定期履行，仍不履行者，得再處怠金或管收','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-4301-053','113-4301',53,'single_choice','債權人甲訴請債務人乙遷讓A 房屋獲勝訴判決確定，乙拒絕搬遷，甲持該判決聲請執行法院強制執 行。下列敘述，何者正確？','執行法院應尊重甲依確定判決執行之權利，不得勸導甲與乙互相讓步，約定自行遷讓之期間','執行法院強制乙遷離後，乙當日夜間折返A 房屋開門進入居住，甲毋須另取得執行名義，得繳納執 行費聲請再為執行','乙之配偶丙，因與乙同居而使用A 房屋，因丙非執行名義之判決當事人，執行法院不得依甲之聲 請，命丙遷離','乙如為孤寡老弱殘障，應由社會福利機關（構）主動關懷協助，執行法院不可勸甲協助乙尋覓暫時 安身處所','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('113-4301-054','113-4301',54,'single_choice','債權人甲為保全對債務人乙之債權新臺幣（下同）500 萬元，聲請法院裁定准許假扣押，甲於收受假 扣押裁定後30 日內，向執行法院聲請查封乙所有價值200 萬元之A 地，經執行後，甲查得乙有另一 筆價值300 萬元之B 地，聲請追加查封。關於甲追加查封之聲請，下列敘述，何者正確？','甲追加查封之聲請，應於第一次查封聲請後30 日內為之，始為合法','甲追加查封之聲請，應於收受假扣押裁定後30 日內為之，始為合法','甲追加查封之聲請，須另行取得假扣押裁定，並於收受該裁定後30 日內為之，始為合法','甲追加查封之聲請，雖已逾收受假扣押裁定、第一次查封聲請30 日，仍屬合法','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-055','113-4301',55,'single_choice','債權人甲聲請法院拍賣債務人乙所有之A 地，經拍定後法院發給拍定人不動產權利移轉證書，乙之 另一債權人丙於價金分配前，聲請對A 地為假扣押之強制執行，執行法院應如何處理？','因執行程序已終結，故不論分配後有無餘額，均駁回丙之執行聲請','通知丙不動產已非乙所有，應另具狀聲請執行賣得價金','將價金依甲、丙之債權比例分配，丙部分並予提存','將甲受償餘額分配給丙並予提存','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-056','113-4301',56,'single_choice','An actor is negligent if, without excuse, he/she violates a statute that is designed to protect against the type of accident that the actor’s conduct causes, and if the accident victim is within the class of persons the statute is designed to protect. Such rule is usually called .','negligence ab initio','negligence bona fide','negligence per se','negligence non liquet','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-057','113-4301',57,'single_choice','Peter signed a release for personal injury before he took a diving class but he was bitten by a sea snake under water. If Peter decides to sue the diving school, what is the strongest argument the school may raise against him?','self-defense','necessity','assumption of the risk','consent','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-058','113-4301',58,'single_choice','The purpose of tort law is to provide relief for the victim for harm actually done, which is expressed in money terms, shall include replacement of property destroyed and reimbursement for medical expenses. Damages for these harm are called .','nominal damages','punitive damages','equitable remedies','compensatory damages','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-059','113-4301',59,'single_choice','A(n) is an agreement made between two contracting parties to allow for the substitution of a new party for an existing one. The new party replaces the original contracting party as a party to the contract. The original party who is replaced gives up any rights it has against the other original party to the contract.','insolvent','novation','third-party beneficiary contract','delegation','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-060','113-4301',60,'single_choice','is an amount of money agreed upon by both parties to a contract which one will pay to the other upon breaching the agreement or if a lawsuit arises due to the breach.','Installment','Liquidated damages','Incidental damages','Punitive damages','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-061','113-4301',61,'single_choice','A(n) is an event, not certain to occur, which must occur, unless its non-occurrence is excused, before performance under a contract becomes due.','condition','predicament','contingency','accustom','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-062','113-4301',62,'single_choice','Based on Taiwan’s Company Act, which of the following can be applied to the public company?','Multiple voting rights shares','Voting Agreement','Restrictions on the transfer of shares','No voting rights shares','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-063','113-4301',63,'single_choice','The term as used in Taiwan’s Securities and Exchange Act means an explanatory written statement that an issuer provides to the general public for the purpose of offering or selling securities.','warranty','proxy statement','representation','prospectus','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('113-4301-064','113-4301',64,'single_choice','A(n) is a person entering or remaining upon land in the possession of another without a privilege to do so created by the possessor’s consent or otherwise, who is not an invitee entering or remaining on the land upon an invitation.','business visitor','social guest','trespasser','offender','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true),
('113-4301-065','113-4301',65,'single_choice','Which of the following statements regarding search and seizure is correct?','A search warrant shall be issued on the basis of reasonable suspicion.','A seizure cannot be used for the purpose of confiscation.','A search warrant should be implemented by first issuing a subpoena duces tecum, if the subject does not comply with the subpoena, then a search warrant will be executed.','A search warrant shall particularly specify the places to be searched and the items or effects to be seized.','法學英文','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],10,10,'parsed','pending_manual_review',null,true)
